class ArgumentParser:
    """
    This is a class for parsing command line arguments to a dictionary.
    """

    def __init__(self):
        self.arguments = {}
        self.required = set()
        self.types = {}

    def add_argument(self, arg, required=False, arg_type=str):
        if required:
            self.required.add(arg)
        self.types[arg] = arg_type

    def _convert_type(self, arg, value):
        if arg in self.types:
            try:
                return self.types[arg](value)
            except (ValueError, TypeError):
                pass
        return value

    def parse_arguments(self, command_string):
        tokens = command_string.split()
        missing_args = set(self.required)
        i = 0

        while i < len(tokens):
            token = tokens[i]
            if token.startswith("--"):  # Long-form argument
                if "=" in token:
                    arg, value = token[2:].split("=", 1)
                    self.arguments[arg] = self._convert_type(arg, value)
                    missing_args.discard(arg)
                else:
                    arg = token[2:]
                    self.arguments[arg] = True
                    missing_args.discard(arg)
            elif token.startswith("-"):  # Short-form argument
                arg = token[1:]
                if i + 1 < len(tokens) and not tokens[i + 1].startswith("-"):
                    value = tokens[i + 1]
                    self.arguments[arg] = self._convert_type(arg, value)
                    missing_args.discard(arg)
                    i += 1
                else:
                    self.arguments[arg] = True
                    missing_args.discard(arg)
            i += 1

        if missing_args:
            return False, missing_args
        return True, None

    def get_argument(self, key):
        return self.arguments.get(key)

