class BinaryDataProcessor:
    """
    This is a class used to process binary data, which includes functions such as clearing non 0 or 1 characters, counting binary string information, and converting to corresponding strings based on different encoding methods.
    """

    def __init__(self, binary_string):
        """
        Initialize the class with a binary string and clean it by removing all non 0 or 1 characters.
        """
        self.binary_string = binary_string
        self.clean_non_binary_chars()

    def clean_non_binary_chars(self):
        """
        Clean the binary string by removing all non 0 or 1 characters.
        """
        self.binary_string = ''.join(char for char in self.binary_string if char in '01')

    def calculate_binary_info(self):
        """
        Calculate the binary string information, including the percentage of 0 and 1, and the total length of the binary string.
        """
        length = len(self.binary_string)
        if length == 0:
            return {'Zeroes': 0, 'Ones': 0, 'Bit length': 0}

        zero_count = self.binary_string.count('0')
        one_count = self.binary_string.count('1')

        return {
            'Zeroes': zero_count / length,
            'Ones': one_count / length,
            'Bit length': length
        }

    def convert_to_ascii(self):
        """
        Convert the binary string to ascii string.
        """
        if len(self.binary_string) % 8 != 0:
            raise ValueError("Binary string length must be a multiple of 8 to convert to ASCII.")

        ascii_string = ''.join(
            chr(int(self.binary_string[i:i+8], 2))
            for i in range(0, len(self.binary_string), 8)
        )
        return ascii_string

    def convert_to_utf8(self):
        """
        Convert the binary string to utf-8 string.
        """
        if len(self.binary_string) % 8 != 0:
            raise ValueError("Binary string length must be a multiple of 8 to convert to UTF-8.")

        # Convert binary string to bytes
        byte_array = bytearray(
            int(self.binary_string[i:i+8], 2)
            for i in range(0, len(self.binary_string), 8)
        )

        try:
            utf8_string = byte_array.decode('utf-8')
        except UnicodeDecodeError:
            raise ValueError("Binary string does not represent valid UTF-8 data.")

        return utf8_string

class BookManagement:
    """
    This is a class as managing books system, which supports to add and remove books from the inventory dict, view the inventory, and check the quantity of a specific book.
    """

    def __init__(self):
        """
        Initialize the inventory of Book Manager.
        """
        self.inventory = {}

    def add_book(self, title, quantity=1):
        """
        Add one or several books to inventory which is sorted by book title.
        :param title: str, the book title
        :param quantity: int, default value is 1.
        """
        if quantity <= 0:
            raise ValueError("Quantity must be a positive integer.")
        if title in self.inventory:
            self.inventory[title] += quantity
        else:
            self.inventory[title] = quantity

    def remove_book(self, title, quantity):
        """
        Remove one or several books from inventory which is sorted by book title.
        Raise false while get invalid input.
        :param title: str, the book title
        :param quantity: int
        """
        if quantity <= 0:
            raise ValueError("Quantity must be a positive integer.")
        if title not in self.inventory:
            raise KeyError(f"Book '{title}' does not exist in inventory.")
        if quantity >= self.inventory[title]:
            del self.inventory[title]
        else:
            self.inventory[title] -= quantity

    def view_inventory(self):
        """
        Get the inventory of the Book Management.
        :return self.inventory: dictionary, {title(str): quantity(int), ...}
        """
        return self.inventory

    def view_book_quantity(self, title):
        """
        Get the quantity of a book.
        :param title: str, the title of the book.
        :return quantity: the quantity of this book title. return 0 when the title does not exist in self.inventory
        """
        return self.inventory.get(title, 0)

class CamelCaseMap:
    """
    This is a custom class that allows keys to be in camel case style by converting them from underscore style, which provides dictionary-like functionality.
    """

    def __init__(self):
        """
        Initialize data to an empty dictionary
        """
        self._data = {}

    def __getitem__(self, key):
        """
        Return the value corresponding to the key
        """
        camel_key = self._convert_key(key)
        return self._data[camel_key]

    def __setitem__(self, key, value):
        """
        Set the value corresponding to the key to the specified value
        """
        camel_key = self._convert_key(key)
        self._data[camel_key] = value

    def __delitem__(self, key):
        """
        Delete the value corresponding to the key
        """
        camel_key = self._convert_key(key)
        del self._data[camel_key]

    def __iter__(self):
        """
        Returning Iterable Objects with Own Data
        """
        return iter(self._data)

    def __len__(self):
        """
        Returns the length of the own data
        """
        return len(self._data)

    def _convert_key(self, key):
        """
        Convert key string into camel case
        """
        return self._to_camel_case(key)

    @staticmethod
    def _to_camel_case(key):
        """
        Convert key string into camel case
        """
        if not key:
            return key
        parts = key.split('_')
        return parts[0] + ''.join(word.capitalize() for word in parts[1:])
